func (o *BootstrapShardChildOptions) WithWorkflowIdConflictPolicy(policy enumsv1.WorkflowIdConflictPolicy) *BootstrapShardChildOptions {
	o.workflowIdConflictPolicy = policy
	return o
}

// BootstrapShardChildRun describes a child BootstrapShard workflow run
type BootstrapShardChildRun struct {
	Future workflow.ChildWorkflowFuture
}

// Get blocks until the workflow is completed, returning the response value
func (r *BootstrapShardChildRun) Get(ctx workflow.Context) (*BootstrapShardOutput, error) {
	var resp BootstrapShardOutput
	if err := r.Future.Get(ctx, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

// Select adds this completion to the selector. Callback can be nil.
func (r *BootstrapShardChildRun) Select(sel workflow.Selector, fn func(*BootstrapShardChildRun)) workflow.Selector {
	return sel.AddFuture(r.Future, func(workflow.Future) {
		if fn != nil {
			fn(r)
		}
	})
}

// SelectStart adds waiting for start to the selector. Callback can be nil.
func (r *BootstrapShardChildRun) SelectStart(sel workflow.Selector, fn func(*BootstrapShardChildRun)) workflow.Selector {
	return sel.AddFuture(r.Future.GetChildWorkflowExecution(), func(workflow.Future) {
		if fn != nil {
			fn(r)
		}
	})
}

// WaitStart waits for the child workflow to start
func (r *BootstrapShardChildRun) WaitStart(ctx workflow.Context) (*workflow.Execution, error) {
	var exec workflow.Execution
	if err := r.Future.GetChildWorkflowExecution().Get(ctx, &exec); err != nil {
		return nil, err
	}
	return &exec, nil
}

// FabricActivities describes available worker activities
type FabricActivities interface{}

// RegisterFabricActivities registers activities with a worker
func RegisterFabricActivities(r worker.ActivityRegistry, activities FabricActivities) {}

// TestClient provides a testsuite-compatible Client
type TestFabricClient struct {
	env       *testsuite.TestWorkflowEnvironment
	workflows FabricWorkflows
}

var _ FabricClient = &TestFabricClient{}

// NewTestFabricClient initializes a new TestFabricClient value
func NewTestFabricClient(env *testsuite.TestWorkflowEnvironment, workflows FabricWorkflows, activities FabricActivities) *TestFabricClient {
	if workflows != nil {
		RegisterFabricWorkflows(env, workflows)
	}
	if activities != nil {
		RegisterFabricActivities(env, activities)
	}
	return &TestFabricClient{env, workflows}
}

// BootstrapShard executes a(n) fabric.v1.BootstrapShard workflow in the test environment
func (c *TestFabricClient) BootstrapShard(ctx context.Context, req *BootstrapShardInput, opts ...*BootstrapShardOptions) (*BootstrapShardOutput, error) {
	run, err := c.BootstrapShardAsync(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return run.Get(ctx)
}

// BootstrapShardAsync executes a(n) fabric.v1.BootstrapShard workflow in the test environment
func (c *TestFabricClient) BootstrapShardAsync(ctx context.Context, req *BootstrapShardInput, options ...*BootstrapShardOptions) (BootstrapShardRun, error) {
	var o *BootstrapShardOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewBootstrapShardOptions()
	}
	opts, err := o.Build(req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing client.StartWorkflowOptions: %w", err)
	}
	return &testBootstrapShardRun{client: c, env: c.env, opts: &opts, req: req, workflows: c.workflows}, nil
}

// GetBootstrapShard is a noop
func (c *TestFabricClient) GetBootstrapShard(ctx context.Context, workflowID string, runID string) BootstrapShardRun {
	return &testBootstrapShardRun{env: c.env, workflows: c.workflows}
}

// CancelWorkflow requests cancellation of an existing workflow execution
func (c *TestFabricClient) CancelWorkflow(ctx context.Context, workflowID string, runID string) error {
	c.env.CancelWorkflow()
	return nil
}

// TerminateWorkflow terminates an existing workflow execution
func (c *TestFabricClient) TerminateWorkflow(ctx context.Context, workflowID string, runID string, reason string, details ...interface{}) error {
	return c.CancelWorkflow(ctx, workflowID, runID)
}

var _ BootstrapShardRun = &testBootstrapShardRun{}

// testBootstrapShardRun provides convenience methods for interacting with a(n) fabric.v1.BootstrapShard workflow in the test environment
type testBootstrapShardRun struct {
	client    *TestFabricClient
	env       *testsuite.TestWorkflowEnvironment
	isStarted atomic.Bool
	opts      *client.StartWorkflowOptions
	req       *BootstrapShardInput
	workflows FabricWorkflows
}

// Cancel requests cancellation of a workflow in execution, returning an error if applicable
func (r *testBootstrapShardRun) Cancel(ctx context.Context) error {
	return r.client.CancelWorkflow(ctx, r.ID(), r.RunID())
}

// Get retrieves a test fabric.v1.BootstrapShard workflow result
func (r *testBootstrapShardRun) Get(context.Context) (*BootstrapShardOutput, error) {
	if r.isStarted.CompareAndSwap(false, true) {
		r.env.ExecuteWorkflow(BootstrapShardWorkflowName, r.req)
	}
	if !r.env.IsWorkflowCompleted() {
		return nil, errors.New("workflow in progress")
	}
	if err := r.env.GetWorkflowError(); err != nil {
		return nil, err
	}
	var result BootstrapShardOutput
	if err := r.env.GetWorkflowResult(&result); err != nil {
		return nil, err
	}
	return &result, nil
}

// ID returns a test fabric.v1.BootstrapShard workflow run's workflow ID
func (r *testBootstrapShardRun) ID() string {
	if r.opts != nil {
		return r.opts.ID
	}
	return ""
}

// Run noop implementation
func (r *testBootstrapShardRun) Run() client.WorkflowRun {
	return nil
}

// RunID noop implementation
func (r *testBootstrapShardRun) RunID() string {
	return ""
}

// Terminate terminates a workflow in execution, returning an error if applicable
func (r *testBootstrapShardRun) Terminate(ctx context.Context, reason string, details ...interface{}) error {
	return r.client.TerminateWorkflow(ctx, r.ID(), r.RunID(), reason, details...)
}
